<?php
declare(strict_types=1);
// Pemasangan sekali pakai: 4 karya awal (kartu di beranda, di atas Video).
// Cara pakai: masuk ke /admin/ lebih dulu, lalu buka /admin/seed-karya.php dan tekan tombolnya.
date_default_timezone_set('Asia/Jakarta');
require __DIR__ . '/lib-artikel.php';

const MARKA = __DIR__ . '/data/karya-awal.done';

$sess = __DIR__ . '/data/sess';
if (is_dir($sess)) {
    session_save_path($sess);
    session_name('adm');
    session_set_cookie_params([
        'lifetime' => 0,
        'path' => '/admin/',
        'httponly' => true,
        'samesite' => 'Lax',
        'secure' => !empty($_SERVER['HTTPS']),
    ]);
    session_start();
}
header('X-Robots-Tag: noindex, nofollow');
header('Cache-Control: no-store');
header('X-Frame-Options: DENY');

$auth = is_file(__DIR__ . '/data/auth.php') ? (array)(include __DIR__ . '/data/auth.php') : [];
$masuk = !empty($_SESSION['ok']) && (int)($_SESSION['sv'] ?? -1) === (int)($auth['sv'] ?? 0);

function halaman(string $isi, int $kode = 200): void
{
    http_response_code($kode);
    echo '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Pasang karya awal</title></head>'
        . '<body style="margin:0;padding:24px;font:16px/1.6 system-ui,sans-serif;background:#f5f6f8;color:#1d2433">'
        . '<div style="max-width:520px;margin:0 auto;background:#fff;border:1px solid #e0e4ea;border-radius:10px;padding:24px">' . $isi . '</div></body></html>';
    exit;
}

if (!$masuk) {
    halaman('<h1 style="font-size:20px;margin:0 0 8px">Belum masuk</h1><p>Masuk dulu ke <a href="/admin/">/admin/</a>, lalu buka halaman ini lagi.</p>', 403);
}

if (is_file(MARKA)) {
    halaman('<h1 style="font-size:20px;margin:0 0 8px">Sudah terpasang</h1><p>Karya awal sudah dipasang sebelumnya. Kelola dari menu <b>Karya</b> di admin.</p><p><a href="/admin/?m=karya">Buka menu Karya</a></p>');
}

$SEED = [
    [
        'judul' => 'Automasi Office & Excel',
        'ringkasan' => 'Automasi VBA dan macro Excel agar pekerjaan berulang dan rekap laporan selesai dalam hitungan detik.',
        'isi' => '<p>Mengotomasi pekerjaan Excel dan Office agar pekerjaan berulang selesai dalam hitungan detik.</p><h2>Yang bisa dikerjakan</h2><ul><li>Automasi VBA</li><li>Macro Excel untuk rekap laporan</li><li>Alur kerja Power Apps, Power Automate, dan Power BI</li></ul><p>Tertarik dengan karya ini? Silakan <a href="/kontak">hubungi saya</a>.</p>',
        'm' => '',
        's' => '',
    ],
    [
        'judul' => 'Pengembangan Website & Aplikasi',
        'ringkasan' => 'Membangun website dan aplikasi, dari basis data dan backend hingga tampilan yang nyaman dipakai.',
        'isi' => '<p>Membangun aplikasi web dan seluler dari basis data, backend, hingga antarmuka.</p><h2>Yang bisa dikerjakan</h2><ul><li>Pengembangan website</li><li>Aplikasi Android</li><li>Aplikasi web full-stack</li></ul><p>Tertarik dengan karya ini? Silakan <a href="/kontak">hubungi saya</a>.</p>',
        'm' => '',
        's' => '',
    ],
    [
        'judul' => 'Multimedia: Desain & Video',
        'ringkasan' => 'Desain grafis, identitas visual, dan penyuntingan video promosi serta profil.',
        'isi' => '<p>Desain grafis, penyuntingan video, dan materi visual untuk komunikasi dan edukasi.</p><h2>Yang bisa dikerjakan</h2><ul><li>Desain grafis dan identitas visual</li><li>Editing video promosi dan profil</li></ul><p>Tertarik dengan karya ini? Silakan <a href="/kontak">hubungi saya</a>.</p>',
        'm' => '',
        's' => '',
    ],
    [
        'judul' => 'UI/UX Designer',
        'ringkasan' => 'Merancang alur dan tampilan yang jelas, nyaman dipakai, dan konsisten di ponsel maupun komputer.',
        'isi' => '<p>Merancang alur dan tampilan yang jelas, nyaman dipakai, dan konsisten di ponsel maupun komputer.</p><p>Tertarik dengan karya ini? Silakan <a href="/kontak">hubungi saya</a>.</p>',
        'm' => '',
        's' => '',
    ],
];

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    $csrf = (string)($_SESSION['csrf'] ?? '');
    if ($csrf === '') {
        $csrf = $_SESSION['csrf'] = bin2hex(random_bytes(16));
    }
    halaman('<h1 style="font-size:20px;margin:0 0 8px">Pasang 4 karya awal</h1>'
        . '<p>Ini akan membuat 4 kartu Karya (sudah terbit) yang tampil di beranda, di atas Video. Semuanya bisa diubah atau dihapus dari menu Karya di admin.</p>'
        . '<form method="post"><input type="hidden" name="csrf" value="' . h($csrf) . '">'
        . '<button type="submit" style="background:#2457c5;color:#fff;border:0;border-radius:6px;padding:10px 18px;font:inherit;font-weight:600;cursor:pointer">Pasang sekarang</button></form>');
}

if (!hash_equals((string)($_SESSION['csrf'] ?? ''), (string)($_POST['csrf'] ?? ''))) {
    halaman('<h1 style="font-size:20px;margin:0 0 8px">Sesi kedaluwarsa</h1><p>Muat ulang halaman ini lalu coba lagi.</p>', 400);
}

art_siapkan();
$dibuat = 0;
$kini = time();
foreach ($SEED as $i => $s) {
    $id = substr(md5('karya-awal-' . ($i + 1)), 0, 16);
    if (art_baca($id) !== null) {
        continue;
    }
    $mid = substr(md5('karya-awal-sampul-' . ($i + 1)), 0, 16);
    $mf = MEDIA_DIR . '/m_' . $mid . '.jpg';
    $sf = MEDIA_DIR . '/s_' . $mid . '.jpg';
    $m = base64_decode($s['m'], true);
    $k = base64_decode($s['s'], true);
    if ($m === false || $k === false || file_put_contents($mf, $m) === false || file_put_contents($sf, $k) === false) {
        halaman('<h1 style="font-size:20px;margin:0 0 8px">Gagal</h1><p>Gambar sampul tidak bisa disimpan di server. Periksa izin folder <code>admin/media</code>.</p>', 500);
    }
    $waktu = date('Y-m-d\TH:i', $kini - 120 - $i * 60);
    $a = [
        'id' => $id,
        'dibuat' => date('Y-m-d H:i'),
        'slug_kunci' => true,
        'judul' => $s['judul'],
        'ringkasan' => $s['ringkasan'],
        'kategori' => 'Karya',
        'tag' => [],
        'penulis' => 'Agus Budiono, S.Pd.',
        'foto' => MEDIA_URL . 'm_' . $mid . '.jpg',
        'foto_ket' => '',
        'isi' => art_bersih_html($s['isi']),
        'status' => 'terbit',
        'waktu' => $waktu,
        'diperbarui' => date('Y-m-d H:i'),
    ];
    $a['slug'] = art_slug($a['judul'], $id);
    art_tulis($a);
    $dibuat++;
}
file_put_contents(MARKA, date('Y-m-d H:i') . "\n", LOCK_EX);
halaman('<h1 style="font-size:20px;margin:0 0 8px">Selesai</h1><p>' . $dibuat . ' karya terpasang. Lihat di <a href="/">beranda</a> atau kelola dari <a href="/admin/?m=karya">menu Karya</a>.</p>');
